(function(){
  var $=function(id){return document.getElementById(id)};

  function sniff(t){
    var head=t.split(/\r?\n/)[0]||'';
    var counts=[[',',0],[';',0],['\t',0],['|',0]].map(function(d){
      var n=0,q=false;
      for(var i=0;i<head.length;i++){
        var c=head[i];
        if(c==='"') q=!q; else if(c===d[0] && !q) n++;
      }
      return [d[0],n];
    });
    counts.sort(function(a,b){return b[1]-a[1]});
    return counts[0][1]>0 ? counts[0][0] : ',';
  }
  function parseCSV(text, delim){
    var rows=[], row=[], field='', q=false, i=0;
    text=text.replace(/^\uFEFF/,'');           // strip the BOM Excel adds
    while(i<text.length){
      var c=text[i];
      if(q){
        if(c==='"'){ if(text[i+1]==='"'){ field+='"'; i++; } else q=false; }
        else field+=c;
      } else {
        if(c==='"') q=true;
        else if(c===delim){ row.push(field); field=''; }
        else if(c==='\n'){ row.push(field); rows.push(row); row=[]; field=''; }
        else if(c==='\r'){ /* handled by the \n */ }
        else field+=c;
      }
      i++;
    }
    if(field!==''||row.length){ row.push(field); rows.push(row); }
    return rows.filter(function(r){ return r.length>1 || (r[0]||'').trim()!==''; });
  }
  function toCSV(rows, delim){
    return rows.map(function(r){
      return r.map(function(v){
        v = v==null ? '' : String(v);
        return /["\n\r]|\Q/.test(v.replace(/\\Q/g,delim)) || v.indexOf(delim)>=0
          ? '"'+v.replace(/"/g,'""')+'"' : v;
      }).join(delim);
    }).join('\r\n');
  }
  function download(name, text, mime){
    var b=new Blob([text],{type:mime||'text/csv;charset=utf-8'});
    var u=URL.createObjectURL(b), a=document.createElement('a');
    a.href=u; a.download=name; document.body.appendChild(a); a.click();
    setTimeout(function(){ URL.revokeObjectURL(u); a.remove(); }, 4000);
  }

  function coerce(v){
    if(!$('types').checked) return v;
    var t=v.trim();
    if(t==='') return '';
    if(/^(true|false)$/i.test(t)) return t.toLowerCase()==='true';
    // only plain numbers; a leading zero means an identifier, not a number,
    // which is exactly the mistake spreadsheets make with postcodes
    if(/^-?(0|[1-9]\d*)(\.\d+)?$/.test(t)){
      var n=Number(t);
      if(String(n)===t || String(n)===t.replace(/^\+/,'')) return n;
    }
    return v;
  }
  function uniqueKeys(head){
    var used=Object.create(null);
    return head.map(function(h,i){
      var base=(h||'').trim()||('column'+(i+1));
      var k=base, n=2;
      while(k in used){ k=base+'_'+n; n++; }
      used[k]=1; return k;
    });
  }
  function run(){
    var text=$('raw').value;
    if(!text.trim()){ $('out').textContent='The JSON appears here'; $('note').textContent='';
      ['nrec','nkey','nsize'].forEach(function(i){$(i).textContent='0'});
      if(window.WT) WT.resize(); return; }
    var d=$('delim').value==='auto'?sniff(text):$('delim').value;
    var rows=parseCSV(text,d);
    if(!rows.length){ $('out').textContent='Nothing could be read from that.'; if(window.WT) WT.resize(); return; }
    var head=uniqueKeys(rows[0]), body=rows.slice(1);
    var shape=$('shape').value, data;
    if(shape==='arrays'){
      data=body.map(function(r){return r.map(coerce)});
    } else if(shape==='keyed'){
      data={};
      body.forEach(function(r){
        var o={};
        for(var i=1;i<head.length;i++) o[head[i]]=coerce(r[i]||'');
        data[r[0]||'']=o;
      });
    } else {
      data=body.map(function(r){
        var o={};
        for(var i=0;i<head.length;i++) o[head[i]]=coerce(r[i]||'');
        return o;
      });
    }
    var json=JSON.stringify(data, null, $('pretty').checked?2:0);
    $('out').textContent=json;
    $('nrec').textContent=body.length;
    $('nkey').textContent=head.length;
    $('nsize').textContent=new Blob([json]).size;
    var dupes=head.filter(function(k){return /_\d+$/.test(k)}).length;
    $('note').textContent = dupes
      ? dupes+' duplicate column name'+(dupes>1?'s were':' was')+' renamed, because JSON keys have to be unique.'
      : 'Read with the '+({',':'comma',';':'semicolon','\t':'tab','|':'pipe'}[d]||d)+' separator.';
    if(window.WT) WT.resize();
  }
  ['raw','delim','shape','types','pretty'].forEach(function(id){
    $(id).addEventListener('input',run); $(id).addEventListener('change',run);
  });
  $('pick').addEventListener('click',function(){$('file').click()});
  $('file').addEventListener('change',function(){load(this.files[0])});
  function load(f){ if(!f) return; var r=new FileReader();
    r.onload=function(){$('raw').value=String(r.result);run()};
    r.onerror=function(){$('note').textContent='That file could not be read.'};
    r.readAsText(f); }
  var drop=$('drop');
  ['dragenter','dragover'].forEach(function(e){drop.addEventListener(e,function(ev){ev.preventDefault();drop.classList.add('over')})});
  ['dragleave','drop'].forEach(function(e){drop.addEventListener(e,function(ev){ev.preventDefault();drop.classList.remove('over')})});
  drop.addEventListener('drop',function(ev){load(ev.dataTransfer.files[0])});
  $('copy').addEventListener('click',function(){
    var ok=WT.copy($('out').textContent);
    this.textContent=ok?'Copied':'Press Ctrl+C';
    var b=this; setTimeout(function(){b.textContent='Copy JSON'},1400);
  });
  $('dl').addEventListener('click',function(){
    download('data.json',$('out').textContent,'application/json');
  });
  $('clear').addEventListener('click',function(){$('raw').value='';run()});
  run();
})();
